module TopModule (
    input  clk,
    input  reset,
    input  [32-1:0] in,
    output [32-1:0] out
);

    reg [32-1:0] out_reg;
    reg [32-1:0] prev_in;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_reg <= 32'b0;
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
            out_reg <= out_reg & (~in) | (out_reg & (~prev_in));
        end
    end

    assign out = out_reg;

endmodule

