    reg [31:0] prev_in;
    reg [31:0] transition_mask;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_reg <= 32'b0;
            prev_in <= 32'b0;
            transition_mask <= 32'b0;
